namespace Remains.Editor {
public static class BattlefieldV2Builder {
 const string Dir="Assets/Remains/BattlefieldV2";
 static Transform root; static System.Random rng; static Material terrainMat,stone,wood,iron,rope,red,cloth,water,foam,cloud;
 static List<Vector2> trail=new List<Vector2>();
 static readonly Vector2[] camps={new Vector2(-178,-35),new Vector2(0,-195),new Vector2(178,-35)};
 static float R(float a,float b)=>a+(b-a)*(float)rng.NextDouble();
 static Vector2 P(float a,float r)=>new Vector2(Mathf.Sin(a)*r,Mathf.Cos(a)*r+8);
 static float Ang(Vector2 p)=>Mathf.Atan2(p.x,p.y-8);
 static float Radius(Vector2 p)=>new Vector2(p.x,p.y-8).magnitude;
 static float Rim(float a)=>292+4*Mathf.Sin(a*7)+3*Mathf.Sin(a*13+1);
 static float Inner(float a)=>91+5*Mathf.Cos(a)+4*Mathf.Sin(a*3+.5f);
 static float Outer(float a)=>Inner(a)+43+3*Mathf.Sin(a*2);
 static float Seg(Vector2 p,Vector2 a,Vector2 b){Vector2 d=b-a;return Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/d.sqrMagnitude));}
 static float Mouth(Vector2 p){float d=999;foreach(float a in new[]{-.70f,.78f}){var start=P(a,117);var mid=P(a+.04f,200);var end=P(a-.02f,315);d=Mathf.Min(d,Seg(p,start,mid),Seg(p,mid,end));}return d;}
 static float PathDist(Vector2 p){float d=Seg(p,new Vector2(0,-195),new Vector2(0,-125));for(int i=1;i<trail.Count;i++)d=Mathf.Min(d,Seg(p,trail[i-1],trail[i]));return d;}
 static float Ground(Vector2 p){
  float a=Ang(p),r=Radius(p),ri=Inner(a),ro=Outer(a);float old=LargeCastleBlockout.TerrainHeight(p.x,p.y);
  float plateau=16+2.1f*Mathf.PerlinNoise(p.x*.013f+12,p.y*.013f+17)+1.1f*Mathf.Sin(p.x*.024f)*Mathf.Cos(p.y*.026f);
  float h;
  if(r<ri-16)h=old;
  else if(r<ri-7)h=Mathf.Lerp(old,7.7f,Mathf.SmoothStep(0,1,(r-ri+16)/9));
  else if(r<ri-1)h=Mathf.Lerp(7.7f,7.15f,(r-ri+7)/6);
  else if(r<ro-2)h=3.4f;
  else h=Mathf.Lerp(3.4f,plateau,Mathf.SmoothStep(0,1,(r-ro+2)/4));
  if(r>ro-3){float m=Mouth(p);h=Mathf.Lerp(3.4f,h,Mathf.SmoothStep(0,1,(m-14)/4));}
  if(p.y < -126 && p.y > -218){float w=1-Mathf.SmoothStep(0,1,(Mathf.Abs(p.x)-8)/14);h=Mathf.Lerp(h,16,w);}
  foreach(var c in camps){float d=Vector2.Distance(p,c);h=Mathf.Lerp(h,17,1-Mathf.SmoothStep(0,1,(d-16)/9));}
  return h;
 }
 static bool Wet(Vector2 p){float r=Radius(p),a=Ang(p);return (r>Inner(a)-1&&r<Outer(a))||(r>Outer(a)-4&&Mouth(p)<16);}
 static Material Mat(string n,Color c){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.name=n;m.color=c;m.SetFloat("_Smoothness",.08f);AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath(Dir+"/"+n+".mat"));return m;}
 static Transform Group(Transform p,string n,Vector3 pos=default){var t=new GameObject(n).transform;t.SetParent(p,false);t.localPosition=pos;return t;}
 static GameObject Primitive(Transform p,string n,PrimitiveType type,Vector3 pos,Vector3 scale,Material m,bool collider=false){var g=GameObject.CreatePrimitive(type);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=m;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;return g;}
 static void Beam(Transform p,string n,Vector3 a,Vector3 b,float rad,Material mat,bool coll=false){var g=Primitive(p,n,PrimitiveType.Cylinder,(a+b)/2,new Vector3(rad*2,(b-a).magnitude/2,rad*2),mat,coll);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static GameObject MeshObj(Transform p,string name,List<Vector3> v,List<int> t,Material mat,List<Color> c=null,bool coll=false){var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetTriangles(t,0);if(c!=null)mesh.SetColors(c);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(Dir+"/"+name+".asset"));var g=Group(p,name).gameObject;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;if(coll)g.AddComponent<MeshCollider>().sharedMesh=mesh;g.isStatic=true;return g;}
 static void Tri(List<Vector3> v,List<int> t,List<Color> c,Vector3 a,Vector3 b,Vector3 d,Color col){int k=v.Count;v.Add(a);v.Add(b);v.Add(d);t.Add(k);t.Add(k+1);t.Add(k+2);if(c!=null){c.Add(col);c.Add(col);c.Add(col);}}
 static Color Surface(Vector2 p,float slope){float h=Ground(p);Color col=Color.Lerp(new Color(.28f,.40f,.14f),new Color(.48f,.56f,.24f),Mathf.PerlinNoise(p.x*.13f+2,p.y*.13f+3));float r=Radius(p),a=Ang(p);if(h<8.1f)col=new Color(.66f,.57f,.37f);if(slope>.65f&&h>8.1f)col=Color.Lerp(new Color(.36f,.37f,.34f),new Color(.57f,.55f,.46f),Mathf.PerlinNoise(p.x*.3f,p.y*.3f));if(r>Outer(a)+4 && PathDist(p)<4.3f)col=new Color(.57f,.43f,.26f);foreach(var cp in camps)if(Vector2.Distance(p,cp)<13)col=new Color(.49f,.40f,.25f);return col;}
 static void Land(){var v=new List<Vector3>();var t=new List<int>();var cs=new List<Color>();float step=2;for(float z=-292;z<308;z+=step)for(float x=-300;x<300;x+=step){var p=new Vector2(x+1,z+1);if(Radius(p)>Rim(Ang(p))+1)continue;Vector3 a=new Vector3(x,Ground(new Vector2(x,z)),z),b=new Vector3(x,Ground(new Vector2(x,z+step)),z+step),c=new Vector3(x+step,Ground(new Vector2(x+step,z+step)),z+step),d=new Vector3(x+step,Ground(new Vector2(x+step,z)),z);float slope=Mathf.Max(Mathf.Abs(a.y-b.y),Mathf.Abs(a.y-d.y))/step;var color=Surface(p,slope);Tri(v,t,cs,a,b,c,color);Tri(v,t,cs,a,c,d,color);}MeshObj(root,"Round_Battlefield_Ground",v,t,terrainMat,cs,true);
  v=new List<Vector3>();t=new List<int>();cs=new List<Color>();for(int i=0;i<360;i++){float a=i*Mathf.PI/180,b=(i+1)*Mathf.PI/180;Vector2 pa=P(a,Rim(a)-1),pb=P(b,Rim(b)-1);Vector2 qa=P(a,Rim(a)+2+2*Mathf.Sin(a*19)),qb=P(b,Rim(b)+2+2*Mathf.Sin(b*19));Color col=Color.Lerp(new Color(.29f,.32f,.34f),new Color(.55f,.52f,.45f),R(0,1));var at=new Vector3(pa.x,Ground(pa),pa.y);var bt=new Vector3(pb.x,Ground(pb),pb.y);var am=new Vector3(qa.x,-12-3*Mathf.Sin(a*17),qa.y);var bm=new Vector3(qb.x,-12-3*Mathf.Sin(b*17),qb.y);var ab=new Vector3(pa.x,-54,pa.y);var bb=new Vector3(pb.x,-54,pb.y);Tri(v,t,cs,at,am,bt,col);Tri(v,t,cs,bt,am,bm,col*.9f);Tri(v,t,cs,am,ab,bm,col*.8f);Tri(v,t,cs,bm,ab,bb,col*.72f);}MeshObj(root,"Outer_Rock_Escarpment",v,t,terrainMat,cs,true);
 }
 static void River(){var v=new List<Vector3>();var t=new List<int>();for(float z=-290;z<308;z+=2)for(float x=-300;x<300;x+=2){Vector2 p=new Vector2(x+1,z+1);if(Radius(p)>Rim(Ang(p))+1||!Wet(p))continue;Tri(v,t,null,new Vector3(x,7,z),new Vector3(x,7,z+2),new Vector3(x+2,7,z+2),Color.white);Tri(v,t,null,new Vector3(x,7,z),new Vector3(x+2,7,z+2),new Vector3(x+2,7,z),Color.white);}MeshObj(root,"Ring_River_Two_Mouths",v,t,water);
  var detail=Group(root,"Water_Ripples");for(int i=0;i<420;i++){var p=P(R(0,Mathf.PI*2),R(85,282));if(!Wet(p))continue;var g=Primitive(detail,"Ripple",PrimitiveType.Cube,new Vector3(p.x,7.03f,p.y),new Vector3(R(.4f,1.8f),.015f,.08f),foam);g.transform.localRotation=Quaternion.Euler(0,R(0,180),0);}
  foreach(float a in new[]{-.70f,.78f}){var p=P(a-.02f,Rim(a));var waterfall=Primitive(root,"Mouth_Waterfall",PrimitiveType.Cube,new Vector3(p.x,-15,p.y),new Vector3(26,44,.7f),water);waterfall.transform.localRotation=Quaternion.Euler(0,a*Mathf.Rad2Deg,0);}
 }
 static Mesh rockMesh;
 static void Rock(Transform parent,string name,Vector3 p,Vector3 size){var g=Group(parent,name,p);g.localRotation=Quaternion.Euler(R(-15,15),R(0,360),R(-12,12));g.localScale=size;g.gameObject.AddComponent<MeshFilter>().sharedMesh=rockMesh;g.gameObject.AddComponent<MeshRenderer>().sharedMaterial=stone;g.gameObject.AddComponent<MeshCollider>().sharedMesh=rockMesh;}
 static void MakeRock(){var v=new List<Vector3>();var t=new List<int>();var cs=new List<Color>();Vector3 top=new Vector3(.1f,.55f,0),bottom=new Vector3(0,-.5f,0);for(int i=0;i<9;i++){float a=i*Mathf.PI*2/9,b=(i+1)*Mathf.PI*2/9;Vector3 p=new Vector3(Mathf.Cos(a)*.5f,.08f*Mathf.Sin(a*3),Mathf.Sin(a)*.5f),q=new Vector3(Mathf.Cos(b)*.5f,.08f*Mathf.Sin(b*3),Mathf.Sin(b)*.5f);Tri(v,t,null,top,q,p,Color.white);Tri(v,t,null,bottom,p,q,Color.white);}var temp=MeshObj(root,"RockPrototype",v,t,stone);rockMesh=temp.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.DestroyImmediate(temp);}
 static void Banks(){var group=Group(root,"River_Bank_Rocks");for(int i=0;i<235;i++){float a=i*Mathf.PI*2/235;float rr=Outer(a)+.8f;var p=P(a,rr);if(Mouth(p)<20||Mathf.Abs(p.x)<8&&p.y<0)continue;float h=Ground(P(a,rr+3));Rock(group,"Outer_Ledge",new Vector3(p.x,(7+h)/2,p.y),new Vector3(R(4,7),h-6,R(3,5)));}
  for(int i=0;i<140;i++){float a=R(0,Mathf.PI*2),rr=Inner(a)-R(7,15);var p=P(a,rr);if(Mathf.Abs(p.x)<11&&p.y<0)continue;float h=Ground(p);Rock(group,"Castle_Rockface",new Vector3(p.x,h-1,p.y),new Vector3(R(3,6),R(4,8),R(3,5)));}
  for(int i=0;i<110;i++){float a=R(0,Mathf.PI*2);var p=P(a,Inner(a)-R(2,7));if(Mathf.Abs(p.x)<10&&p.y<0)continue;Rock(group,"Beach_Boulder",new Vector3(p.x,Ground(p)+.2f,p.y),Vector3.one*R(1,3));}
 }
 static void Torus(Transform p,Vector3 pos,float radius,float tube,Material mat,string name){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<=20;i++)for(int j=0;j<=6;j++){float a=i*Mathf.PI*2/20,b=j*Mathf.PI*2/6;v.Add(pos+new Vector3(tube*Mathf.Sin(b),(radius+tube*Mathf.Cos(b))*Mathf.Cos(a),(radius+tube*Mathf.Cos(b))*Mathf.Sin(a)));}for(int i=0;i<20;i++)for(int j=0;j<6;j++){int k=i*7+j;t.AddRange(new[]{k,k+7,k+1,k+1,k+7,k+8});}MeshObj(p,name,v,t,mat);}
 static void Tent(Transform p){var v=new List<Vector3>();var t=new List<int>();var cs=new List<Color>();int n=20;for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n,b=(i+1)*Mathf.PI*2/n;Vector3 lo=new Vector3(Mathf.Sin(a)*5,0,Mathf.Cos(a)*5),lob=new Vector3(Mathf.Sin(b)*5,0,Mathf.Cos(b)*5);Vector3 hi=new Vector3(Mathf.Sin(a)*5.2f,4.4f,Mathf.Cos(a)*5.2f),hib=new Vector3(Mathf.Sin(b)*5.2f,4.4f,Mathf.Cos(b)*5.2f);Color col=i%4<2?new Color(.55f,.08f,.09f):new Color(.14f,.16f,.18f);if(i!=0&&i!=19){Tri(v,t,cs,lo,hib,hi,col);Tri(v,t,cs,lo,lob,hib,col);}Tri(v,t,cs,hi,hib,new Vector3(0,8.1f,0),col*1.1f);}var g=MeshObj(p,"Clean_Open_Tent",v,t,terrainMat,cs,true);g.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.TwoSided;Beam(p,"Centre_Pole",Vector3.zero,new Vector3(0,8.8f,0),.14f,wood,true);Primitive(p,"Flag",PrimitiveType.Cube,new Vector3(1,8.6f,0),new Vector3(2,.7f,.05f),red);for(int i=0;i<10;i++){float a=i*Mathf.PI/5;Vector3 from=new Vector3(Mathf.Sin(a)*5.2f,4.2f,Mathf.Cos(a)*5.2f),to=new Vector3(Mathf.Sin(a)*7.3f,0,Mathf.Cos(a)*7.3f);Beam(p,"Guy_Rope",from,to,.035f,rope);Beam(p,"Peg",to-Vector3.up*.2f,to+Vector3.up*.4f,.065f,iron);}}
 static void Cart(Transform p){Primitive(p,"Bed",PrimitiveType.Cube,new Vector3(0,1.5f,0),new Vector3(2.7f,.25f,4.2f),wood,true);for(int i=0;i<6;i++)foreach(float x in new[]{-1.4f,1.4f})Primitive(p,"Side_Board",PrimitiveType.Cube,new Vector3(x,1.7f+i*.18f,0),new Vector3(.12f,.16f,4.2f),wood,true);foreach(float z in new[]{-1.3f,1.3f}){Beam(p,"Axle",new Vector3(-1.8f,.98f,z),new Vector3(1.8f,.98f,z),.12f,iron);foreach(float x in new[]{-1.65f,1.65f}){var hub=new Vector3(x,.98f,z);Torus(p,hub,.88f,.11f,wood,"Wheel_Rim");Torus(p,hub,.91f,.035f,iron,"Iron_Tyre");for(int j=0;j<8;j++){float a=j*Mathf.PI/4;Beam(p,"Spoke",hub,hub+new Vector3(0,Mathf.Cos(a)*.85f,Mathf.Sin(a)*.85f),.055f,wood);}}}foreach(float x in new[]{-.85f,.85f})Beam(p,"Shaft",new Vector3(x,1.4f,1.5f),new Vector3(x,1,5),.10f,wood);for(int i=0;i<3;i++){var box=Primitive(p,"Supplies_Crate",PrimitiveType.Cube,new Vector3(i%2*1.2f-.6f,2.1f,i/2*1.3f-.8f),new Vector3(1.05f,1,1.05f),wood,true);for(int s=0;s<2;s++)Primitive(p,"Crate_Iron",PrimitiveType.Cube,box.transform.localPosition+new Vector3(0,0,s==0?-.32f:.32f),new Vector3(1.08f,1.03f,.06f),iron);}}
 static void Camps(){for(int i=0;i<3;i++){var p=camps[i];var g=Group(root,new[]{"Attack_Camp_West","Attack_Camp_South","Attack_Camp_East"}[i],new Vector3(p.x,Ground(p),p.y));g.localRotation=Quaternion.Euler(0,i==0?90:i==2?-90:0,0);Tent(Group(g,"Tent"));Cart(Group(g,"Supply_Wagon",new Vector3(10,0,-1)));}}
 static void Plant(string name,Vector2 p,float height,Transform parent){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Remains/MapKit/Models/"+name+".glb");var wrapper=Group(parent,name,new Vector3(p.x,Ground(p)-.1f,p.y));var g=UnityEngine.Object.Instantiate(source,wrapper);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;var rs=g.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);float scale=height/bounds.size.y;g.transform.localScale*=scale;bounds=rs[0].bounds;foreach(var r in rs){r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Remains/MapKit/Materials/MapKit_VertexColor.mat");bounds.Encapsulate(r.bounds);}g.transform.position+=new Vector3(p.x-bounds.center.x,wrapper.position.y-bounds.min.y,p.y-bounds.center.z);wrapper.localRotation=Quaternion.Euler(0,R(0,360),0);var c=wrapper.gameObject.AddComponent<CapsuleCollider>();c.height=height*.55f;c.radius=.45f;c.center=new Vector3(0,c.height/2,0);}
 static bool Clear(Vector2 p){if(Wet(p)||Radius(p)<Outer(Ang(p))+9||Radius(p)>Rim(Ang(p))-9||Mouth(p)<23||PathDist(p)<8)return false;foreach(var c in camps)if(Vector2.Distance(p,c)<23)return false;return true;}
 static void Plants(){var group=Group(root,"Trees_And_Firs");int trees=0;for(int i=0;i<11000&&trees<820;i++){var p=P(R(0,Mathf.PI*2),R(145,284));if(!Clear(p)||Mathf.PerlinNoise(p.x*.027f+8,p.y*.027f+7)<.43f)continue;Plant(R(0,1)<.58f?"Tree_Pine":"Tree_Deciduous",p,R(8,15),group);trees++;}
  var v=new List<Vector3>();var t=new List<int>();var cs=new List<Color>();for(int i=0;i<20000;i++){var p=P(R(0,Mathf.PI*2),R(140,287));if(!Clear(p))continue;float y=Ground(p);Color color=Color.Lerp(new Color(.21f,.33f,.10f),new Color(.56f,.62f,.26f),R(0,1));for(int j=0;j<3;j++){float a=R(0,6.28f),h=R(.3f,.8f),w=.16f;Vector3 b=new Vector3(p.x,y,p.y),dx=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a))*w;Vector3 tip=b+Vector3.up*h+dx*.8f;Tri(v,t,cs,b-dx,tip,b+dx,color);Tri(v,t,cs,b+dx,tip,b-dx,color);}}MeshObj(root,"Three_Dimensional_Grass",v,t,terrainMat,cs);
 }
 static void Ropes(){var g=Group(root,"Climb_Ropes");foreach(float a in new[]{-2.7f,-2.1f,-1.55f,-1.1f,.1f,1.12f,1.6f,2.1f,2.7f}){var bank=P(a,Outer(a)+3.4f);if(Mouth(bank)<22)continue;var below=P(a,Outer(a)-3);var top=new Vector3(bank.x,Ground(bank)+.25f,bank.y);var bottom=new Vector3(below.x,3.6f,below.y);var r=Group(g,"Climbable_Rope");Beam(r,"Iron_Stake",top-Vector3.up*.8f,top+Vector3.up*.7f,.12f,iron);var lip=new Vector3(bottom.x,top.y+.5f,bottom.z);Beam(r,"Rope_Over_Lip",top+Vector3.up*.5f,lip,.09f,rope);Beam(r,"Thick_Rope",lip,bottom,.09f,rope);for(int j=0;j<10;j++)Primitive(r,"Knot",PrimitiveType.Sphere,Vector3.Lerp(bottom,lip,j/10f),Vector3.one*.24f,rope);var c=r.gameObject.AddComponent<Remains.BattlefieldClimbRope>();c.bottom=bottom;c.top=top+new Vector3(Mathf.Sin(a)*1.4f,0,Mathf.Cos(a)*1.4f);}}
 static void Atmosphere(){var g=Group(root,"Mist_Below_Cliffs");for(int i=0;i<90;i++){float a=i*Mathf.PI*2/90;var p=P(a,R(295,320));Primitive(g,"Mist_Billow",PrimitiveType.Sphere,new Vector3(p.x,R(-51,-38),p.y),new Vector3(R(23,48),R(12,22),R(25,45)),cloud);}var sky=Group(root,"Stylized_Clouds");for(int i=0;i<14;i++){var p=P(i*Mathf.PI*2/14,R(335,380));var bank=Group(sky,"Cloud",new Vector3(p.x,R(75,120),p.y));for(int j=0;j<5;j++)Primitive(bank,"Cloud_Lobe",PrimitiveType.Sphere,new Vector3(j*8-16,R(-2,4),R(-4,4)),new Vector3(R(17,28),R(8,15),R(12,22)),cloud);}}
 public static void Build(){Directory.CreateDirectory(Dir);Directory.CreateDirectory("output/battlefield-v2");rng=new System.Random(10326);trail.Clear();for(int i=0;i<=80;i++){float a=Mathf.Lerp(-Mathf.PI/2-.25f,-Mathf.PI*1.5f+.25f,i/80f);trail.Add(P(a,182+5*Mathf.Sin(i*.3f)));} // west -> south -> east
  var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.SaveScene(scene,"Assets/Remains/Scenes/Backups/RoundMap_BeforeBattlefieldV2.unity",true);
  var old=GameObject.Find("Map_LargeCastle_Blockout");if(old)UnityEngine.Object.DestroyImmediate(old);var previous=GameObject.Find("Battlefield_V2");if(previous)UnityEngine.Object.DestroyImmediate(previous);
  var castle=LargeCastleBlockout.Build();foreach(string n in new[]{"Terrain_360m_Hill_Riverbed","River"}){var tr=castle.transform.Find(n);if(tr)UnityEngine.Object.DestroyImmediate(tr.gameObject);}root=Group(null,"Battlefield_V2");
  terrainMat=new Material(Shader.Find("Remains/StylizedLandscape"));AssetDatabase.CreateAsset(terrainMat,AssetDatabase.GenerateUniqueAssetPath(Dir+"/Landscape.mat"));stone=Mat("Warm_Rock",new Color(.49f,.48f,.42f));wood=Mat("Oak",new Color(.38f,.23f,.11f));iron=Mat("Dark_Iron",new Color(.16f,.18f,.19f));rope=Mat("Hemp",new Color(.55f,.40f,.22f));red=Mat("Tent_Red",new Color(.55f,.08f,.09f));cloth=Mat("Tent_Charcoal",new Color(.13f,.15f,.18f));water=Mat("Turquoise_River",new Color(.12f,.48f,.54f));water.SetFloat("_Smoothness",.6f);foam=Mat("Foam",new Color(.6f,.8f,.77f));cloud=Mat("Cloud_Mist",new Color(.79f,.85f,.87f));
  Land();River();MakeRock();Banks();Camps();Plants();Ropes();Atmosphere();
  var castleStone=new Material(Shader.Find("Remains/CastleStone"));AssetDatabase.CreateAsset(castleStone,AssetDatabase.GenerateUniqueAssetPath(Dir+"/CastleMasonry.mat"));foreach(var renderer in castle.GetComponentsInChildren<MeshRenderer>()){var m=renderer.sharedMaterial;if(m && (m.name=="Wall_Stone" || m.name=="Edge_Stone"))renderer.sharedMaterial=castleStone;}
  var player=castle.GetComponentInChildren<Remains.CastleWalkthrough>();player.spawn=new Vector3(0,16.05f,-145);player.transform.position=player.spawn;
  var cam=castle.transform.Find("OverviewCamera").GetComponent<Camera>();cam.transform.position=new Vector3(260,380,-490);cam.transform.LookAt(new Vector3(0,0,10));cam.orthographic=true;cam.orthographicSize=335;cam.farClipPlane=1800;cam.backgroundColor=new Color(.63f,.73f,.80f);cam.enabled=true;
  var main=GameObject.Find("Main Camera");if(main&&main.GetComponent<Camera>())main.GetComponent<Camera>().enabled=false;
